import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// Whether the app's agent joins the DAP hub network as a live member
/// (issue #402 AC3), and with which connection. Persisted as JSON at
/// `agent_network.json` in the root of the sandbox filesystem
/// ([ExecutionEnv.cwd]) — same tiny-store pattern as `apps_home_mode.json`.
///
/// The hub URL and pairing token ride the same shape as the CLI's
/// `~/.dap/config.json` connection, but live app-side: the agent
/// membership is this app's own decision (E3 — no scanning magic, the
/// address + token are entered by hand, prefilled for the macOS
/// loopback default).
class AgentNetworkStore {
  AgentNetworkStore._(
    this._env,
    this._enabled,
    this._url,
    this._token,
    this._name,
  );

  /// A store without persistence (tests): setters flip memory only.
  AgentNetworkStore.inMemory()
    : _env = null,
      _enabled = false,
      _url = defaultAgentNetworkUrl,
      _token = '',
      _name = defaultAgentNetworkName;

  /// File name (under [ExecutionEnv.cwd]) the store persists to.
  static const fileName = 'agent_network.json';

  /// Schema version of the JSON envelope.
  static const _version = 1;

  /// The zero-config macOS loopback default (mirrors the CLI).
  static const defaultAgentNetworkUrl = 'ws://127.0.0.1:8787/ws';

  /// The default agent display name on the hub roster.
  static const defaultAgentNetworkName = 'app-agent';

  final ExecutionEnv? _env;
  bool _enabled;
  String _url;
  String _token;
  String _name;

  bool get enabled => _enabled;
  String get url => _url;
  String get token => _token;
  String get name => _name;

  /// Loads the settings persisted in [env]; a missing, unreadable, or
  /// corrupt file yields the first-run default (off — joining the network
  /// is an explicit opt-in).
  static Future<AgentNetworkStore> load(ExecutionEnv env) async {
    var settings = const _AgentNetworkSettings();
    try {
      settings = await _readPersistedSettings(env) ?? settings;
      // Corrupt or incompatible file → the defaults, never crash boot.
    } on Object {
      // (handled above: fall through to the defaults)
    }
    return AgentNetworkStore._(
      env,
      settings.enabled,
      settings.url,
      settings.token,
      settings.name,
    );
  }

  /// The settings persisted in `agent_network.json`, or null when the file
  /// is absent or not the stored schema version.
  static Future<_AgentNetworkSettings?> _readPersistedSettings(
    ExecutionEnv env,
  ) async {
    final text = (await env.readTextFile('${env.cwd}/$fileName')).valueOrNull;
    if (text == null) return null;
    return _decodeSettings(jsonDecode(text));
  }

  static _AgentNetworkSettings? _decodeSettings(Object? decoded) {
    if (decoded is! Map<String, dynamic> || decoded['version'] != _version) {
      return null;
    }
    return _AgentNetworkSettings(
      enabled: decoded['enabled'] == true,
      url: '${decoded['url'] ?? defaultAgentNetworkUrl}'.trim(),
      token: '${decoded['token'] ?? ''}',
      name: _decodedName(decoded),
    );
  }

  /// The stored agent name, trimmed; blank falls back to the default.
  static String _decodedName(Map<String, dynamic> decoded) {
    final savedName = '${decoded['name'] ?? defaultAgentNetworkName}'.trim();
    return savedName.isEmpty ? defaultAgentNetworkName : savedName;
  }

  Future<void> _persist() async {
    final env = _env;
    if (env == null) return;
    try {
      await env.writeFile(
        '${env.cwd}/$fileName',
        jsonEncode({
          'version': _version,
          'enabled': _enabled,
          'url': _url,
          'token': _token,
          'name': _name,
        }),
      );
    } on Object {
      // Best effort: an unwritable root keeps the app running; the
      // settings just do not survive the restart.
    }
  }

  Future<void> setEnabled(bool value) async {
    _enabled = value;
    await _persist();
  }

  Future<void> setConnection({String? url, String? token, String? name}) async {
    if (url != null && url.trim().isNotEmpty) _url = url.trim();
    if (token != null) _token = token;
    if (name != null && name.trim().isNotEmpty) _name = name.trim();
    await _persist();
  }
}

/// The decoded file contents of a [AgentNetworkStore.load]: first-run
/// defaults unless the stored JSON overrides them.
class _AgentNetworkSettings {
  const _AgentNetworkSettings({
    this.enabled = false,
    this.url = AgentNetworkStore.defaultAgentNetworkUrl,
    this.token = '',
    this.name = AgentNetworkStore.defaultAgentNetworkName,
  });

  final bool enabled;
  final String url;
  final String token;
  final String name;
}

import 'dart:io';

import 'package:flutter/foundation.dart' show kIsWeb;

import 'package:fa/services/project_folder_channel.dart';
import 'package:fa/services/project_mount_env.dart';
import 'package:fa/services/project_mount_store.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// Shared flow for changing the user-selected project folder (macOS only):
/// pick → resolve security-scoped bookmark → persist → apply to the mount
/// env → notify the host (typically `agent.refreshProjectMountPrompt`).
/// Extracted so the file browser, the chat header's workspace chip, and
/// tests all drive it through one code path.

/// Picks a directory and applies it as the project mount. Returns the
/// picked host path on success, null when cancelled or unsupported.
/// Surfaces access failures via [onAccessDenied]; tells the host the
/// environment changed via [onApplied] (pass the service's
/// `refreshProjectMountPrompt` to recompose the agent's system prompt).
Future<String?> pickAndApplyProjectMount({
  required ExecutionEnv env,
  required void Function() onApplied,
  ProjectFolderOps? ops,
  void Function()? onAccessDenied,
}) async {
  final mountEnv = _resolveMountEnv(env);
  if (mountEnv == null) return null;
  final resolvedOps = ops ?? _defaultOps();
  if (resolvedOps == null) return null;
  final picked = await resolvedOps.pickDirectory();
  if (picked == null) return null;
  final ok = await resolvedOps.startAccessing(picked.bookmark);
  if (!ok) {
    onAccessDenied?.call();
    return null;
  }
  await ProjectMountStore.save(
    env,
    path: picked.path,
    bookmark: picked.bookmark,
    // Preserve the current scoped state across re-picks; default false
    // for a fresh /project.
    scoped: mountEnv.scoped,
  );
  mountEnv.mountedRoot = picked.path;
  mountEnv.mountUnavailable = null;
  onApplied();
  return picked.path;
}

/// Unmounts the current project folder (best effort) and notifies the host.
/// Returns true when a mount was cleared.
Future<bool> unapplyProjectMount({
  required ExecutionEnv env,
  required void Function() onApplied,
  ProjectFolderOps? ops,
}) async {
  final mountEnv = _resolveMountEnv(env);
  final root = mountEnv?.mountedRoot;
  if (mountEnv == null || root == null) return false;
  final resolvedOps = ops ?? _defaultOps();
  final stored = await ProjectMountStore.load(env);
  if (stored != null && resolvedOps != null) {
    await resolvedOps.stopAccessing(stored.bookmark);
  }
  await ProjectMountStore.clear(env);
  mountEnv.mountedRoot = null;
  onApplied();
  return true;
}

/// The host path the project mount currently resolves to, or null when no
/// folder is mounted (the agent works in its container root).
String? currentMountedPath(ExecutionEnv env) =>
    _resolveMountEnv(env)?.mountedRoot;

/// Whether the active mount is scoped (tool restriction flag on).
bool? currentMountedScoped(ExecutionEnv env) => _resolveMountEnv(env)?.scoped;

/// Toggles the 'restrict tools to this folder' flag without re-picking
/// the folder: updates [ProjectMountEnv.scoped] in place, persists the
/// new flag via [ProjectMountStore.save] (re-using the existing path +
/// bookmark), and recomposes the agent's prompt. Returns true when the
/// toggle landed. No-op when nothing is mounted (nothing to scope TO).
Future<bool> setProjectMountScoped({
  required ExecutionEnv env,
  required bool scoped,
  required void Function() onApplied,
}) async {
  final target = await _scopedMountTarget(env);
  if (target == null) {
    return false;
  }
  final (mountEnv, stored) = target;
  mountEnv.scoped = scoped;
  await ProjectMountStore.save(
    env,
    path: stored.path,
    bookmark: stored.bookmark,
    scoped: scoped,
  );
  onApplied();
  return true;
}

/// The mount target of the scoped toggle: `(mountEnv, stored record)`, or
/// null when any precondition is missing.
Future<(ProjectMountEnv, ProjectMountStore)?> _scopedMountTarget(
  ExecutionEnv env,
) async {
  final mountEnv = _mountedProjectEnv(env);
  if (mountEnv == null) {
    return null;
  }
  final stored = await ProjectMountStore.load(env);
  if (stored == null) {
    return null;
  }
  return (mountEnv, stored);
}

/// The mount env only when a folder is actually mounted (nothing mounted
/// means nothing to scope TO).
ProjectMountEnv? _mountedProjectEnv(ExecutionEnv env) {
  final mountEnv = _resolveMountEnv(env);
  return mountEnv?.mountedRoot == null ? null : mountEnv;
}

/// Whether native directory picking is available on this platform (macOS).
bool projectFolderPickingSupported() {
  if (kIsWeb) return false;
  return Platform.isMacOS;
}

ProjectMountEnv? _resolveMountEnv(ExecutionEnv env) {
  var e = env;
  if (e is SecretsExecutionEnv) e = e.delegate;
  return e is ProjectMountEnv ? e : null;
}

ProjectFolderOps? _defaultOps() => ProjectFolderChannelOps.isSupported
    ? const ProjectFolderChannelOps()
    : null;

